using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Users;using Namaa.Api.Extensions;using Namaa.Application.Users.Commands.UpdateUser;using Namaa.Application.Users.Queries.GetUserById;using Namaa.Application.Users.Queries.GetUsers;namespace Namaa.Api.Controllers;[ApiController][Route("api/users")]public sealed class UsersController(ISender sender):ControllerBase{[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetUsersQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetUserByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateUserRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateUserCommand(id,request.RoleId,request.FullName,request.Email,request.PhoneNumber,request.IsActive),cancellationToken)).ToActionResult(this);}
